 items=''.join(f'<a href="{link(name)}"{(" aria-current=\"page\"" if active==name else "")}>{name}</a>' for name in ['Live Demos','Selected Work','About','FAQ'])
 return f'''<a class="skip" href="#main">Skip to content</a><header class="site-header"><nav class="nav" aria-label="Main navigation"><a class="brand" href="{link('Home')}" aria-label="Sukhjindra Web Studio home"><span class="brand-mark">SW</span><span><span class="brand-name">Sukhjindra Web Studio</span><span class="brand-sub">Design • Develop • Refine</span></span></a><button class="nav-toggle" type="button" data-nav-toggle aria-controls="primary-menu" aria-expanded="false" aria-label="Toggle navigation">{icon('menu')}</button><div class="nav-links" id="primary-menu" data-nav><a href="{link('Home')}"{(' aria-current="page"' if active=='Home' else '')}>Home</a><div class="nav-dropdown" data-service-menu><button type="button" class="nav-drop-toggle" data-service-toggle aria-expanded="false">Services {icon('chevron')}</button><div class="nav-menu">{services}</div></div>{items}<a class="nav-cta" href="{UPWORK}" target="_blank" rel="noopener noreferrer">Visit My Upwork {icon('external')}</a></div></nav></header>'''
