repairs=[('Broken layout','Before: overlapping cards and awkward offsets. After: a balanced, flexible grid.','layout','Misaligned margins and compressed gaps','Use gap-based flex layout and normal element flow.','.cards { display:flex; gap:12px; }'),('Mobile overflow','Before: a row becomes wider than its container. After: cards wrap correctly.','mobile','Fixed widths push content beyond the viewport','Use flex-wrap and flexible card widths.','.cards { display:flex; flex-wrap:wrap; }'),('JavaScript button','Before: a sample action has no connected behavior. After: it gives immediate feedback.','js','Missing click handler','Attach an event listener and update a status element.','button.addEventListener("click", showFeedback);'),('Inconsistent CSS','Before: clashing fonts, inconsistent alignment and poor contrast. After: coordinated visual design.','css','Scattered styles without shared tokens','Apply consistent type, spacing and color variables.','.card { color:var(--ink); gap:12px; }')]
