repair+=f'''<section class="section soft"><div class="container">{section_head('METHOD & QUALITY','Diagnose the cause. Fix the behavior.','A useful frontend repair should remain understandable and stable after the visible symptom disappears.')}<div class="grid three">{''.join(f'<article class="facts-card surface">{icon(ic,True)}<h3 style="margin:20px 0 9px">{t}</h3><p>{d}</p></article>' for ic,t,d in [('wrench','Reproduce','Understand the exact device, steps and expected behavior.'),('code','Isolate & correct','Make a targeted, reviewable change instead of masking symptoms.'),('shield','Retest','Check the original problem and related responsive states.')])}</div></div></section>'''
repair+=f'<section class="section"><div class="container">{section_head("QUESTIONS","About frontend fixes",center=True)}{faq([("Can you fix one bug without rebuilding the website?","Often, yes. The right approach depends on the existing code and the cause of the issue."),("Can you work with an existing HTML/CSS/JS website?","These demonstrations focus on the HTML, CSS and JavaScript layer of websites. Other stacks need a review of their dependencies and deployment process."),("Do these examples reproduce real customer issues?","No. They are intentionally created demonstration cases showing repair techniques, not fabricated claims of paid customer work.")])}</div></section>'+CLOSING
out('services/bug-fixes/index.html',doc('Bug Fixes','HTML CSS & JavaScript Bug Fixes | Sukhjindra Web Studio','Test four interactive before-and-after frontend repair demonstrations.',repair))

chat=pagehero('FAQ Chatbots','SERVICE 03 / GUIDED SUPPORT','Helpful answers, delivered through an <span class="blue">interactive assistant.</span>','A well-structured FAQ assistant can help people navigate common questions. Try three distinct fictional business contexts—no paid API required.','#chat-playground','Try the chat assistant')
chat+=f'''<section class="section"><div class="container">{section_head('LIVE FAQ CHAT','Change the business. Ask a real question.','This is a working rule-based FAQ assistant—not an AI language model and not a connection to real customer or order records.')}<div class="config-grid" id="chat-playground"><aside class="side-note"><h3>Choose a sample business</h3><div class="field"><label for="chat-context">Knowledge base</label><select id="chat-context" data-chat-context><option value="store">Morrow Market · Online store</option><option value="services">Alder & Co. · Services</option><option value="education">Brightpath Learning · Education</option></select></div><p>The colors and answers are demonstration content. Switch contexts to see different supported questions.</p>{points(['Typed questions','Suggested prompts','Session chat history','Helpful unknown-answer fallback','Keyboard-friendly inputs'])}<p class="note" style="margin-top:20px">Please do not enter private or payment information. No chat transcript is uploaded to a server.</p></aside><div class="chat-shell" data-chat><div class="chat-head"><span class="chat-avatar">{icon('chat',True)}</span><div><h3 data-chat-brand>Morrow Market · Guided FAQ demo</h3><p>Sample business · no live agent</p></div><span class="status">● Demo active</span></div><div class="chat-log" role="log" aria-live="polite" aria-label="Chat messages" data-chat-log></div><div class="chat-suggestions" aria-label="Suggested questions" data-chat-suggestions></div><form class="chat-form" data-chat-form><label for="chat-input" class="sr-only" style="position:absolute;left:-9999px">Your question</label><input id="chat-input" data-chat-input maxlength="400" autocomplete="off" placeholder="Ask a question about the sample business…" required><button class="btn small" type="submit">Send {icon('arrow')}</button></form><div class="chat-meta"><span class="note">Guided FAQ demo · not generative AI</span><button type="button" data-chat-reset>Clear conversation</button></div></div></div></div></section>'''
chat+=f'''<section class="section soft"><div class="container">{section_head('BEHIND THE INTERFACE','Simple technology. Carefully defined scope.')}<div class="grid three">{''.join(f'<article class="facts-card surface"><span class="service-icon">{icon(ic)}</span><h3>{t}</h3><p>{d}</p></article>' for ic,t,d in [('layers','Structured knowledge','Sample question-and-answer datasets differ by business context.'),('chat','Helpful conversations','Keyword intent matching, a graceful fallback and relevant suggested questions.'),('shield','No fictional integrations','The assistant cannot access real orders, private records, bookings or staff.')])}</div></div></section>'''
chat+=f'<section class="section"><div class="container">{section_head("QUESTIONS","About FAQ chatbots",center=True)}{faq([("Is this chatbot powered by AI?","No. The default demonstration is deterministic FAQ matching. A generative AI integration would require a protected service, separate credentials and additional safety checks."),("Does this collect customer data?","No chat is transmitted to a backend; the example works directly in the visitor’s browser. A real installation would need an appropriate privacy and data-handling design."),("Can the assistant answer anything?","No. It matches supported business topics and gives a candid fallback when its knowledge is insufficient. This is deliberate and more trustworthy than inventing answers."),("Could it connect to business systems later?","Potentially, with a separately scoped and securely authenticated backend integration. This demo does not claim that functionality.")])}</div></section>'+CLOSING
out('services/chatbots/index.html',doc('Chatbots','Functional FAQ Website Chatbot | Sukhjindra Web Studio','Try a free, working FAQ chatbot across three fictional business contexts, with keyboard support and honest limitations.',chat,'<script type="module" src="/web-studio/js/chatbot.js"></script>'))

sign=pagehero('HTML Email Signatures','SERVICE 04 / EMAIL SIGNATURES','Every email can look <span class="blue">considered and professional.</span>','Choose a style, edit fictional sample information, preview the result and export real table-based HTML with clickable links.','#signature-lab','Explore signature styles')
